import Foundation
assert(BoardDebate.maxRounds == 3)
assert(BoardDebate.seats == ["cto", "research", "projects"])
assert(BoardDebate.clean(topic: "  Ship   the\nboardroom? ") == "Ship the boardroom?")
assert(BoardDebate.clean(topic: " a ") == nil)
let turns = [BoardDebate.Turn(seat: "cto", round: 1, text: "Ship behind a flag."), BoardDebate.Turn(seat: "research", round: 1, text: "Show evidence first.")]
let opening = BoardDebate.turnPrompt(topic: "Ship it?", round: 1, seat: "cto", turns: [])
assert(opening.contains("Ship it?") && opening.contains("opening position") && opening.contains("round 1 of at most 3"))
let reply = BoardDebate.turnPrompt(topic: "Ship it?", round: 2, seat: "projects", turns: turns)
assert(reply.contains("Round 1 · Chief Technology Officer: Ship behind a flag.") && reply.contains("Round 1 · Director of Research: Show evidence first."))
assert(BoardDebate.turnSystem(persona: "PERSONA").hasPrefix("PERSONA") && BoardDebate.turnSystem(persona: "P").contains("at most 45 words"))
print("PASS: debate prompts carry the question, the round and every earlier turn")
assert(BoardDebate.verdict(from: "{\"agreed\": true, \"decision\": \"Ship Friday behind a flag.\"}") == BoardDebate.Verdict(agreed: true, decision: "Ship Friday behind a flag."))
assert(BoardDebate.verdict(from: "```json\n{\"agreed\":false,\"decision\":\"Research wants evidence; CTO wants to ship.\"}\n```")?.agreed == false)
assert(BoardDebate.verdict(from: "Here you go: {\"agreed\":true,\"decision\":\"**Ship it**\"} done")?.decision == "Ship it")
assert(BoardDebate.verdict(from: "They agree.") == nil)
assert(BoardDebate.verdict(from: "{\"agreed\":\"yes\",\"decision\":\"x\"}") == nil)
assert(BoardDebate.verdict(from: "{\"agreed\":true,\"decision\":\"  \"}") == nil)
print("PASS: the chair verdict is read only from real JSON with a boolean and a decision")
assert(BoardDebate.spoken("CTO: **Ship it**  now.\n") == "Ship it now.")
assert(BoardDebate.spoken("Director of Research — Evidence first.") == "Evidence first.")
let long = String(repeating: "Word ", count: 120) + "end."
assert(BoardDebate.spoken(long).count <= 321 && BoardDebate.spoken(long).hasSuffix("…"))
let sentences = String(repeating: "This is a sentence. ", count: 30)
assert(BoardDebate.spoken(sentences).hasSuffix("."))
print("PASS: debate turns become clean single bubble lines without name prefixes or markdown")
let agreed = BoardDebate.summary(topic: "Ship it?", turns: turns, verdict: .init(agreed: true, decision: "Ship Friday."), rounds: 2, chair: "claude-sonnet-5-5")
assert(agreed.hasPrefix("Agreed after 2 rounds: Ship Friday.") && agreed.contains("Chair call: claude-sonnet-5-5") && agreed.contains("Show evidence first."))
assert(BoardDebate.summary(topic: "x", turns: turns, verdict: .init(agreed: false, decision: "Split."), rounds: 3, chair: "c").hasPrefix("No consensus after 3 rounds: Split."))
assert(BoardDebate.summary(topic: "x", turns: turns, verdict: nil, rounds: 1, chair: "c").hasPrefix("The chair call returned no usable verdict after 1 round."))
print("PASS: the task list records the outcome honestly, the chair model, and the full transcript")
assert(BoardDebate.announcement(verdict: .init(agreed: true, decision: "Ship Friday."), rounds: 2) == "The board agreed after 2 rounds: Ship Friday.")
assert(BoardDebate.announcement(verdict: .init(agreed: false, decision: "Research wants evidence first."), rounds: 3).hasPrefix("The board did not reach consensus after 3 rounds."))
assert(BoardDebate.announcement(verdict: nil, rounds: 1).contains("could not summarise"))
assert(BoardDebate.acknowledgement(seats: ["cto", "research", "projects"]).contains("Chief Technology Officer, Director of Research and Director of Projects are debating"))
assert(BoardDebate.acknowledgement(seats: ["cto", "projects"]).contains("Chief Technology Officer and Director of Projects"))
print("PASS: Jarvis acknowledges who is debating and announces the verdict, or says plainly when there is none")
